INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (14,14,'["Quelles méthodes utilisez-vous pour planifier et suivre l''avancement d''un chantier de génie civil en phase d''exécution, et quels outils de gestion de projet maîtrisez-vous ?", "Comment gérez-vous un écart significatif entre le budget prévisionnel et le coût réel d''un projet en cours de réalisation ?", "Face à un désaccord technique avec un bureau d''études ou un entrepreneur sur le respect des normes de construction, quelle démarche adoptez-vous pour trancher et assurer la conformité des travaux ?", "Pouvez-vous décrire le projet le plus complexe que vous avez supervisé depuis votre sortie de l''EHTP en 2020, et quel était votre rôle précis dans sa conduite ?", "Au cours de vos 6 années d''expérience, avez-vous travaillé sur des projets d''infrastructure publique ou d''aménagement urbain, et quelles contraintes spécifiques avez-vous rencontrées ?", "Qu''est-ce qui a le plus évolué dans votre manière de gérer des projets entre votre première année professionnelle et aujourd''hui ?", "Pourquoi souhaitez-vous rejoindre l''ADER Fès-Meknès à ce stade de votre carrière, et qu''espérez-vous apporter concrètement à l''agence ?", "Où vous projetez-vous professionnellement dans 5 ans, et en quoi ce poste de CGM s''inscrit-il dans cette trajectoire ?", "Que savez-vous des missions et des projets portés par l''ADER Fès-Meknès, et quel est selon vous le défi territorial le plus urgent auquel la région doit répondre ?", "Le secteur public impose des contraintes réglementaires et des délais de décision souvent différents du privé — comment vous adapteriez-vous à ce cadre, et l''avez-vous déjà expérimenté ?"]','[]','{}','2026-08-27 13:28:18.000225') ON CONFLICT (id) DO NOTHING;